// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        bool ok;
        try c.buyDrugs{value: 1}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
